import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.G0y0PQA7.js";const n="/relio/shots/en/file-new-dialog.png",i="/relio/shots/en/file-recent-menu.png",p=JSON.parse('{"title":"File","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/file.md","filePath":"en/features/file.md"}'),s={name:"en/features/file.md"};function d(l,e,h,c,g,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="file" tabindex="-1">File <a class="header-anchor" href="#file" aria-label="Permalink to &quot;File&quot;">​</a></h1><p>What you do from the File menu and document tabs: new, open, save, recent files, document tabs, and automatic backup and recovery.</p><p>If you are new to Relio, start with <a href="/relio/en/quick/start">Install and open your first file</a> and <a href="/relio/en/quick/from-ermaster">Coming from ERMaster</a> in Quick start.</p><h2 id="file-menu" tabindex="-1">File menu <a class="header-anchor" href="#file-menu" aria-label="Permalink to &quot;File menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>Shortcut</th><th>What it does</th></tr></thead><tbody><tr><td>File › New diagram</td><td><kbd>Ctrl</kbd>+<kbd>N</kbd></td><td>Opens an empty document after you choose the database type and target version.</td></tr><tr><td>File › Open…</td><td><kbd>Ctrl</kbd>+<kbd>O</kbd></td><td>Opens an <code>.erm</code> file.</td></tr><tr><td>File › Recent files ▸</td><td></td><td>Recently opened files. <strong>Clear list</strong> at the bottom empties it.</td></tr><tr><td>File › Close</td><td><kbd>Ctrl</kbd>+<kbd>W</kbd></td><td>Closes the current document tab.</td></tr><tr><td>File › Save</td><td><kbd>Ctrl</kbd>+<kbd>S</kbd></td><td>Saves the current document.</td></tr><tr><td>File › Save as…</td><td><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>S</kbd></td><td>Saves to a new location or name.</td></tr><tr><td>File › Save again in sorted order</td><td></td><td>Saves again in Git-friendly order even when nothing changed. See &quot;Sorted saving&quot; below.</td></tr><tr><td>File › Compare and merge ▸</td><td></td><td>Comparing and merging two models. See <a href="/relio/en/features/git">Git and merging</a>.</td></tr><tr><td>File › Git history</td><td></td><td>Opens or closes the Git history panel for this file. <a href="/relio/en/features/git">Git and merging</a></td></tr><tr><td>File › Import ▸</td><td></td><td>From DB…, From file…, From SQL, DBML, Mermaid or Markdown… — <a href="/relio/en/features/import">Import and other formats</a> · <a href="/relio/en/features/database">Databases</a></td></tr><tr><td>File › Export ▸</td><td></td><td>From DDL… to Model JSON… — <a href="/relio/en/features/ddl">DDL</a> · <a href="/relio/en/features/export">Export</a></td></tr><tr><td>File › Export to DB…</td><td></td><td>Creates the model directly in a database. <a href="/relio/en/features/database">Databases</a></td></tr><tr><td>File › Page setup… · Print…</td><td><kbd>Ctrl</kbd>+<kbd>P</kbd> (print)</td><td><a href="/relio/en/features/export#printing">Export › Printing</a></td></tr><tr><td>File › Exit</td><td></td><td>Closes Relio. If there are unsaved documents, it asks <strong>Save and exit</strong> or <strong>Exit without saving</strong>.</td></tr></tbody></table><h2 id="creating-a-diagram" tabindex="-1">Creating a diagram <a class="header-anchor" href="#creating-a-diagram" aria-label="Permalink to &quot;Creating a diagram&quot;">​</a></h2><p>File › New diagram (<kbd>Ctrl</kbd>+<kbd>N</kbd>) opens the new diagram dialog.</p><ul><li><strong>Database</strong> — Choose one of the 12 supported databases. For MySQL, also choose the <strong>Target product</strong> (MySQL or MariaDB).</li><li><strong>Target version</strong> — The database version you will actually use. If you leave it unset, it shows &quot;version not set&quot;, and design checks and DDL use the syntax available from the lowest supported version of that database (for example PostgreSQL 9.4). If unsure, leave it as is.</li><li>Click <strong>Create</strong> to open a new untitled tab. You choose the location and name when you save for the first time.</li></ul><p>The target version is remembered per file on this PC, not inside the <code>.erm</code> file; on another PC you choose it again. To change it later, click the left end of the status bar (for example &quot;PostgreSQL 16&quot;) to open the Database tab of the options dialog.</p><figure class="shot" data-scene="file-new-dialog"><img src="'+n+'" alt="New diagram dialog — choosing the database and target version" loading="lazy"><figcaption>New diagram dialog — choosing the database and target version</figcaption></figure><h2 id="opening-files" tabindex="-1">Opening files <a class="header-anchor" href="#opening-files" aria-label="Permalink to &quot;Opening files&quot;">​</a></h2><ul><li>Choose File › Open… (<kbd>Ctrl</kbd>+<kbd>O</kbd>) or drag an <code>.erm</code> file onto the window. Several files open as separate tabs.</li><li>Opening a file that is already open takes you to its tab.</li><li>Opening or dropping an <code>.sql</code>, <code>.ddl</code>, <code>.dbml</code>, <code>.mmd</code>, <code>.mermaid</code> or <code>.md</code> file does not add it right away; it opens the <a href="/relio/en/features/import">import dialog</a>. Files are imported one at a time.</li><li><strong>Open a sample</strong> — On the start screen or in Help › Open sample ▸, choose <strong>PostgreSQL — online bookstore</strong> (19 tables) or <strong>MySQL — users and permissions</strong> (16 tables). Samples are built into the app, so they open without the internet, and they open as a new untitled document (a copy), so your changes never touch the sample. Saving opens the Save as dialog.</li></ul><h3 id="opening-a-damaged-file" tabindex="-1">Opening a damaged file <a class="header-anchor" href="#opening-a-damaged-file" aria-label="Permalink to &quot;Opening a damaged file&quot;">​</a></h3><p>A damaged file is repaired as far as possible and opened. The &quot;Opened after repairing damaged parts&quot; window then lists the repairs in a table of <strong>Location · Entries · Original value · Interpreted value</strong>, and the same entries are kept in the problem list. Items you should look at are marked &quot;Needs review&quot; and shown first in yellow. <strong>Copy list</strong> copies the table. Saving stores the repaired contents.</p><p>A file that still has Git merge conflict markers (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>) cannot be opened as is. Resolve it right away with <strong>Resolve Git merge conflict…</strong> in the notice. See <a href="/relio/en/features/git#merging">Git and merging</a>.</p><h2 id="recent-files" tabindex="-1">Recent files <a class="header-anchor" href="#recent-files" aria-label="Permalink to &quot;Recent files&quot;">​</a></h2><p>File › Recent files ▸ shows each file name with its folder. The first nine are numbered. Files that have since disappeared are dimmed and cannot be opened. <strong>Clear list</strong> at the bottom empties the list. In the recent files list on the start screen, <strong>Remove from list</strong> removes entries one at a time.</p><figure class="shot" data-scene="file-recent-menu"><img src="'+i+'" alt="File › Recent files submenu — file names and folders, and Clear list" loading="lazy"><figcaption>File › Recent files submenu — file names and folders, and Clear list</figcaption></figure><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><ul><li><strong>Save</strong> (<kbd>Ctrl</kbd>+<kbd>S</kbd>) is available when something has changed. A new document or a sample copy that has never been saved opens the Save as dialog.</li><li>Relio writes a temporary file completely and then swaps it in for the original. Even if the app stops while saving, the original file is not damaged.</li><li>A changed document shows <code>*</code> before its name on the document tab.</li><li>When you close a document with unsaved changes, Relio asks <strong>Save</strong> · <strong>Don&#39;t save</strong> · <strong>Cancel</strong>.</li></ul><h3 id="when-the-file-changed-outside-relio" tabindex="-1">When the file changed outside Relio <a class="header-anchor" href="#when-the-file-changed-outside-relio" aria-label="Permalink to &quot;When the file changed outside Relio&quot;">​</a></h3><p>If another program or another person changed the file since you last opened or saved it, the &quot;The file was changed outside Relio&quot; window appears just before saving.</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td>Merge…</td><td>Opens a merge tab that combines your changes and the outside changes at the model level.</td></tr><tr><td>Show differences</td><td>Stops saving and opens the outside file and your document in a comparison tab. You are asked again when you save.</td></tr><tr><td>Overwrite (discard outside changes)</td><td>Discards the outside changes and overwrites the file with your document. A copy of the file before overwriting is kept in the automatic backup folder.</td></tr><tr><td>Save as…</td><td>Saves to a different file.</td></tr><tr><td>Cancel</td><td>Does not save.</td></tr></tbody></table><p>If the file was deleted or moved, the &quot;The file you are saving no longer exists&quot; window lets you choose <strong>Save again here</strong>.</p><h3 id="when-you-return-to-the-window" tabindex="-1">When you return to the window <a class="header-anchor" href="#when-you-return-to-the-window" aria-label="Permalink to &quot;When you return to the window&quot;">​</a></h3><p>If an open file is changed outside Relio, the &quot;Another program changed the file&quot; window appears when you come back to the window. With no unsaved changes, choose <strong>Reload</strong> or <strong>Leave as is</strong>; with unsaved changes, choose <strong>Merge…</strong>, <strong>Reload (discard my changes)</strong> or <strong>Keep my changes</strong>. If the open file was deleted, Relio tells you &quot;The file no longer exists&quot; and keeps the document open; saving creates the file again at that location.</p><h3 id="sorted-saving" tabindex="-1">Sorted saving <a class="header-anchor" href="#sorted-saving" aria-label="Permalink to &quot;Sorted saving&quot;">​</a></h3><p>When <strong>Save in Git-friendly order</strong> is on in Tools › Settings › General (the default), lists are saved in a fixed order. Git diffs get smaller and the file still opens in ERMaster. The first save of a file after you turn this on can change many lines, so save just the reordering with File › Save again in sorted order and commit it on its own — later changes are then easier to review.</p><h2 id="document-tabs" tabindex="-1">Document tabs <a class="header-anchor" href="#document-tabs" aria-label="Permalink to &quot;Document tabs&quot;">​</a></h2><ul><li>Each open file gets one tab. Drag tabs to reorder them.</li><li><kbd>Ctrl</kbd>+<kbd>Tab</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Tab</kbd> go to the next and previous tab.</li><li>A middle click on a tab closes it.</li><li>Right-click a tab for <strong>Close</strong> · <strong>Close other tabs</strong> · <strong>Close all</strong> · <strong>Copy path</strong> · <strong>Show in folder</strong>.</li><li>Double-click a tab to collapse the right and bottom panels at once and give the canvas more room. <a href="/relio/en/features/canvas#panels-and-the-start-screen">Canvas and palette</a></li></ul><h2 id="after-a-restart" tabindex="-1">After a restart <a class="header-anchor" href="#after-a-restart" aria-label="Permalink to &quot;After a restart&quot;">​</a></h2><p>The files that were open when you quit are reopened in the same tab order, with the tab you were viewing in front. Files that no longer exist are skipped, and if none are left you get the start screen. To turn this off, clear <strong>Reopen last session&#39;s documents at startup</strong> in Tools › Settings › General.</p><h2 id="automatic-backup-and-recovery" tabindex="-1">Automatic backup and recovery <a class="header-anchor" href="#automatic-backup-and-recovery" aria-label="Permalink to &quot;Automatic backup and recovery&quot;">​</a></h2><ul><li>While there are unsaved changes, Relio keeps the latest 10 copies per file in the <code>backup</code> folder of the settings folder at a set interval (5 minutes by default). Change the interval in <strong>Automatic backup interval (minutes)</strong> in Tools › Settings › General; 0 turns it off.</li><li>If Relio did not shut down normally, the &quot;Recover unsaved documents&quot; window appears the next time it starts. Check the document, original file and backup time, choose what to recover and click <strong>Recover</strong>. <strong>Do not recover</strong> skips it, and <strong>Open backup folder</strong> shows the files directly.</li><li>A recovered document opens as changed. Saving it replaces the original file. The backup files stay where they are.</li></ul><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Where backups and settings are kept is listed in <a href="/relio/en/features/troubleshooting#where-your-data-is-stored">Help and troubleshooting › Where your data is stored</a>.</p></div>',35)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
